package com.campusnova.service; import com.campusnova.dto.FaqRequest; import com.campusnova.model.*; import com.campusnova.repository.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class FaqService { private final FaqRepository faqs; private final CategoryRepository categories; public FaqService(FaqRepository f,CategoryRepository c){faqs=f;categories=c;} public List<Faq> all(String query){return query==null||query.trim().isEmpty()?faqs.findAll():faqs.findByQuestionContainingIgnoreCaseOrAnswerContainingIgnoreCase(query,query);} public Faq save(FaqRequest r){Category c=categories.findByNameIgnoreCase(r.getCategory()).orElseGet(()->categories.save(new Category(r.getCategory(),"•"))); return faqs.save(new Faq(c,r.getQuestion(),r.getAnswer(),r.getKeywords()));} public Faq update(Long id,FaqRequest r){Faq f=faqs.findById(id).orElseThrow(()->new NoSuchElementException("FAQ not found")); Category c=categories.findByNameIgnoreCase(r.getCategory()).orElseThrow(()->new NoSuchElementException("Category not found")); f.setCategory(c);f.setQuestion(r.getQuestion());f.setAnswer(r.getAnswer());f.setKeywords(r.getKeywords());return faqs.save(f);} public void delete(Long id){faqs.deleteById(id);} }
